import heapq
from typing import Mapping, Optional, Tuple, List


def heaviest_route(limits: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    if src not in limits or dst not in limits:
        raise KeyError(f"Source {src} or destination {dst} not found in limits")
    if src == dst:
        raise ValueError("Source and destination must be different")

    # pq stores: (-min_load, length, path)
    pq = [(-float('inf'), 0, [src])]
    visited = {}

    while pq:
        neg_load, length, path = heapq.heappop(pq)
        load = -neg_load
        u = path[-1]

        if u == dst:
            return (int(load) if load != float('inf') else 0, path)

        # Prune if we've reached u with a better load
        if u in visited and visited[u] > load:
            continue
        visited[u] = load

        for v, weight in limits.get(u, {}).items():
            if v in path:
                continue
            new_load = min(load, weight)
            heapq.heappush(pq, (-new_load, length + 1, path + [v]))

    return None"
    }
  }
}
