import heapq
from typing import Mapping, Optional, Tuple, List

def shortest_path(adj: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    """
    Find the shortest route between two depots with deterministic tie-breaking.

    Tie rule: 
    1. Total km (lowest wins)
    2. Number of legs (lowest wins)
    3. Lexicographically smallest list of depot codes (lowest wins)
    """
    if src not in adj:
        return None
    if src == dst:
        return (0, [src])

    # priority queue stores: (distance, num_legs, path)
    # path is stored as a list; heapq will compare lists lexicographically
    pq = [(0, 0, [src])]
    # visited stores the best (distance, num_legs, path) found so far for each node
    visited = {src: (0, 0, [src])}

    while pq:
        (dist, legs, path) = heapq.heappop(pq)
        u = path[-1]

        if u == dst:
            return (dist, path)

        # If we found a better path to u already, skip
        if (dist, legs, path) > visited.get(u, (float('inf'), float('inf'), [])):
            continue

        for v, weight in adj.get(u, {}).items():
            new_dist = dist + weight
            new_legs = legs + 1
            new_path = path + [v]
            new_state = (new_dist, new_legs, new_path)

            if v not in visited or new_state < visited[v]:
                visited[v] = new_state
                heapq.heappush(pq, new_state)

    return None
