from typing import Iterable, Tuple, List
from collections import defaultdict

def critical_roads(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str]]:
    """
    Find roads whose closure would split a region.
    If multiple roads exist between the same pair of depots, none of them are critical.
    """
    edge_list = list(edges)
    if not edge_list:
        return []

    adj = defaultdict(list)
    counts = defaultdict(int)
    for u, v, w in edge_list:
        if u == v: continue
        pair = tuple(sorted((u, v)))
        counts[pair] += 1
        adj[u].append(v)
        adj[v].append(u)

    discovery_time = {}
    low_link = {}
    bridges = set()
    timer = 0

    def dfs(u, p=None):
        nonlocal timer
        discovery_time[u] = low_link[u] = timer
        timer += 1

        for v in adj[u]:
            if v == p: continue
            if v in discovery_time:
                low_link[u] = min(low_link[u], discovery_time[v])
            else:
                dfs(v, u)
                low_link[u] = min(low_link[u], low_link[v])
                if low_link[v] > discovery_time[u]:
                    pair = tuple(sorted((u, v)))
                    if counts[pair] == 1:
                        bridges.add(pair)

    nodes = sorted(list(adj.keys()))
    for node in nodes:
        if node not in discovery_time:
            dfs(node)

    return sorted(list(bridges))"}}}
