from typing import Iterable, Tuple, List
from routekit.build_adjacency import build_adjacency

def critical_roads(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str]]:
    """
    Find roads whose closure would split a region.
    """
    edge_list = list(edges)
    adj_map = build_adjacency(edge_list)
    nodes = list(adj_map.keys())
    if not nodes:
        return []

    edge_counts = {}
    for u, v, w in edge_list:
        pair = tuple(sorted((u, v)))
        edge_counts[pair] = edge_counts.get(pair, 0) + 1

    visited = {}
    low = {}
    timer = 0
    bridges = []

    def dfs(u, p=None):
        nonlocal timer
        visited[u] = low[u] = timer
        timer += 1
        for v in adj_map.get(u, []):
            if v == p:
                continue
            if v in visited:
                low[u] = min(low[u], visited[v])
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > visited[u]:
                    pair = tuple(sorted((u, v)))
                    if edge_counts[pair] == 1:
                        bridges.append(pair)

    for node in nodes:
        if node not in visited:
            dfs(node)

    return sorted(bridges)
